unsigned char is_mac_address(unsigned char *addr)
{

	unsigned int addr_int = ((*(addr + 5)) << 16) + ((*(addr + 4)) << 8) + (*(addr + 3));
	int size = sizeof(apple_mac_array) / sizeof(unsigned int);
	for (int i = 0; i < size; i++) {

		if (addr_int == apple_mac_array[i])
			return 1;
	}

	return 0;
}
